"""Static build for Resources & Insights.
Source of truth: data/resources.json (admin-ready article records).
Generates: resources.html, resources/<slug>.html, js/resources-data.js, sitemap.xml, robots.txt.
Rules: drafts are never generated or listed; placeholders are shown only when config.showPlaceholders is true and are always noindex and left out of the sitemap."""
import json,re,html,os,datetime
os.chdir(os.path.dirname(os.path.abspath(__file__)))
R=json.load(open('data/resources.json'));cfg=R['config'];site=R['site'];SU=site['url'].rstrip('/');au=site['author']
cats={c['id']:c for c in R['categories']};E=html.escape
def vis(a):return a['status']=='published' or (a['status']=='placeholder' and cfg.get('showPlaceholders'))
V=sorted([a for a in R['articles'] if vis(a)],key=lambda a:a['order'])
def words(h):return len(re.sub(r'<[^>]+>',' ',h).split())
for a in V:
    if a['status']=='published' and not a.get('readingTime'):a['readingTime']=max(1,round(words(a['content'])/200))
def fd(d):return datetime.date.fromisoformat(d).strftime('%b %d, %Y').replace(' 0',' ') if d else 'Date TBD'
def rt(a):return f"{a['readingTime']} min read" if a.get('readingTime') else 'Reading time TBD'
FONTS='<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Sora:wght@600;700;800&display=swap" rel="stylesheet">'
ARROW='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>'
def head(p,title,desc,canon,robots,og,ld=''):
    return f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{E(title)}</title>
<meta name="description" content="{E(desc)}"><meta name="robots" content="{robots}"><meta name="theme-color" content="#101827"><link rel="canonical" href="{E(canon)}">
<meta property="og:type" content="{'article' if '/resources/' in canon else 'website'}"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{E(canon)}"><meta property="og:image" content="{E(og)}"><meta name="twitter:card" content="summary_large_image">
{ld}{FONTS}
<script>document.documentElement.classList.add('js')</script>
<link rel="stylesheet" href="{p}css/styles.css">
</head>
<body>
<a class="skip" href="#main">Skip to content</a>
<div class="ambient" aria-hidden="true"><i class="blob b1"></i><i class="blob b2"></i><i class="blob b3"></i></div>
'''
def nav(p):
    L=[('Home','index.html'),('About','about.html'),('Services','index.html#services'),('Portfolio','portfolio.html'),('Resources','resources.html')]
    items=''.join(f'<a{" class=\"on\" aria-current=\"page\"" if n=="Resources" else ""} href="{p}{h}">{n}</a>' for n,h in L)
    return f'<header class="nav"><div class="wrap"><a class="logo" href="{p}index.html"><i>RH</i>Raja Hamza Pervaiz</a><button class="burger" aria-label="Toggle menu" aria-expanded="false">&#9776;</button><nav class="menu" aria-label="Main">{items}<a class="btn" href="{p}contact.html">Contact</a></nav></div></header>\n'
def foot(p):
    return f'''<footer><div class="wrap"><div class="fg">
<div><a class="logo" href="{p}index.html"><i>RH</i>Raja Hamza Pervaiz</a><p>SEO Specialist focused on organic growth, technical optimization, and AI search visibility.</p></div>
<div><h4>Quick Links</h4><ul><li><a href="{p}index.html">Home</a></li><li><a href="{p}about.html">About</a></li><li><a href="{p}index.html#services">Services</a></li><li><a href="{p}portfolio.html">Portfolio</a></li><li><a href="{p}resources.html">Resources</a></li><li><a href="{p}contact.html">Contact</a></li></ul></div>
<div><h4>Connect</h4><div class="soc" id="social"></div></div></div>
<p class="copy">© 2026 Raja Hamza Pervaiz. All rights reserved.</p></div></footer>
'''
def cta(p):
    return f'<section class="cta" id="contact"><div class="wrap rv"><h2>Have an SEO Challenge Worth Discussing?</h2><p>Whether you\'re working on technical SEO, local search, organic growth, or AI search visibility, let\'s exchange ideas and explore opportunities.</p><div class="ctas"><a class="btn" href="{p}portfolio.html">Explore My Portfolio</a><a class="btn ghost" href="{p}contact.html">Get In Touch</a></div></div></section>\n'
def badge(a):return '<span class="smp">Sample placeholder</span>' if a['status']=='placeholder' else ''
# ---------- data js (no article bodies, no drafts)
pub=[{k:v for k,v in a.items() if k!='content'} for a in V]
open('js/resources-data.js','w').write('/* generated by build.py from data/resources.json */\nwindow.RESOURCES='+json.dumps(dict(config=dict(showPlaceholders=cfg.get('showPlaceholders',False),newsletterEndpoint=cfg.get('newsletterEndpoint')),categories=R['categories'],articles=pub),ensure_ascii=False)+';\n')
# ---------- listing
nos='<noscript><ul>'+''.join(f'<li><a href="resources/{a["slug"]}.html">{E(a["title"])}</a></li>' for a in V)+'</ul></noscript>'
lp=head('','Resources & Insights | SEO Guides by Raja Hamza Pervaiz','Practical SEO guides, technical insights, local search strategies, and emerging developments in GEO and AEO by Raja Hamza Pervaiz.',SU+'/resources','index,follow',SU+'/assets/res-local.svg')
lp+=nav('')+f'''<main id="main">
<section class="rh"><div class="wrap">
<p class="label stg" style="--d:.1s">THE KNOWLEDGE HUB</p>
<h1 class="stg" style="--d:.2s">Resources &amp; Insights</h1>
<p class="lead2 stg" style="--d:.3s">Practical SEO Knowledge for a Changing Search Landscape.</p>
<p class="desc stg" style="--d:.4s">Explore practical SEO guides, technical insights, local search strategies, and emerging developments in Generative Engine Optimization and Answer Engine Optimization. My goal is to share useful knowledge that helps marketers, SEO professionals, and businesses improve their search visibility.</p>
<form class="sb stg" id="sf" role="search" style="--d:.5s"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/></svg><input id="q" type="search" placeholder="Search articles, guides, and SEO topics..." aria-label="Search articles" autocomplete="off"><button type="button" id="qc" aria-label="Clear search">&times;</button></form>
<p class="topics stg" style="--d:.6s">Technical SEO | Local SEO | Content Strategy | GEO | AEO | AI Search</p>
</div></section>
<section class="fl" id="feat-sec"><div class="wrap"><article class="feat" id="feat"></article></div></section>
<section class="topicbar"><div class="wrap"><h2>Explore Topics</h2><div class="tabs" id="tabs" role="group" aria-label="Filter articles by category"></div><div class="chips" id="chips"></div></div></section>
<section class="la" id="articles"><div class="wrap"><div class="head rv"><h2>Latest Articles &amp; Guides</h2><p>Explore practical insights, tutorials, and strategies covering different aspects of modern SEO.</p></div>
<p class="count" id="count" aria-live="polite"></p><p class="notice2" id="note" role="status"></p>
<div class="pgrid" id="grid"></div>
<div class="none" id="none"><b>No articles match your search.</b>Try a different keyword or browse another topic.<br><button class="btn ghost" id="reset" type="button">Reset search and filters</button></div>
{nos}</div></section>
<section class="nl"><div class="wrap"><div class="nlb rv"><div><h2>Stay Updated on the World of SEO</h2><p>Get practical SEO insights, useful guides, and updates on the evolving search landscape.</p></div><form id="nlf" novalidate><div class="nlf"><input id="nle" type="email" placeholder="Your email address" aria-label="Email address" autocomplete="email"><button class="btn" type="submit">Subscribe</button></div><p class="nls" id="nls" role="status" aria-live="polite"></p></form></div></div></section>
{cta('')}</main>
'''+foot('')+'<script src="js/content.js"></script><script src="js/icons.js"></script><script src="js/resources-data.js"></script><script src="js/resources.js"></script>\n</body></html>'
open('resources.html','w').write(lp)
# ---------- articles
def slug(s):return re.sub(r'[^a-z0-9]+','-',re.sub(r'<[^>]+>','',s).lower()).strip('-')
def related(a):
    sc=[]
    for b in V:
        if b is a:continue
        s=(100 if b['id'] in a.get('related',[]) else 0)+(3 if b['category']==a['category'] else 0)+2*len(set(a['tags'])&set(b['tags']))
        sc.append((-s,b['order'],b))
    return [x[2] for x in sorted(sc,key=lambda x:(x[0],x[1]))[:3]]
os.makedirs('resources',exist_ok=True)
for f in os.listdir('resources'):os.remove('resources/'+f)
for i,a in enumerate(V):
    p='../';used=set();toc=[]
    def hid(m):
        lv,t=m.group(1),m.group(2);s=slug(t) or 'section';b=s;n=2
        while s in used:s=f'{b}-{n}';n+=1
        used.add(s);toc.append((lv,s,re.sub(r'<[^>]+>','',t)));return f'<h{lv} id="{s}">{t}</h{lv}>'
    body=re.sub(r'<h([23])>(.*?)</h\1>',hid,a['content']).replace('{{p}}',p)
    body=re.sub(r'<table>.*?</table>',lambda m:'<div class="tw">'+m.group(0)+'</div>',body,flags=re.S)
    tochtml=''.join(f'<li><a class="l{lv}" href="#{s}">{E(t)}</a></li>' for lv,s,t in toc)
    canon=a.get('canonical') or f'{SU}/resources/{a["slug"]}';robots='index,follow' if a['status']=='published' else 'noindex,nofollow'
    c=cats[a['category']];img=SU+'/'+a['ogImage']
    ld='<script type="application/ld+json">'+json.dumps({"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":SU+"/"},{"@type":"ListItem","position":2,"name":"Resources","item":SU+"/resources"},{"@type":"ListItem","position":3,"name":a['title'],"item":canon}]})+'</script>\n'
    if a['status']=='published':
        ld+='<script type="application/ld+json">'+json.dumps({"@context":"https://schema.org","@type":"BlogPosting","headline":a['title'],"description":a['metaDescription'],"image":img,"author":{"@type":"Person","name":a['author']},"datePublished":a['date'],"dateModified":a.get('updated') or a['date'],"mainEntityOfPage":canon})+'</script>\n'
    pg=head(p,a.get('seoTitle') or a['title'],a['metaDescription'],canon,robots,img,ld)+nav(p)
    ban='<p class="sampleban"><b>Sample placeholder.</b> This is not a published article. It shows how an article page will look once real content is added.</p>' if a['status']=='placeholder' else ''
    pv=V[i-1] if i>0 else None;nx=V[i+1] if i<len(V)-1 else None
    pn=(f'<a href="{pv["slug"]}.html"><small>&larr; Previous</small><span>{E(pv["title"])}</span></a>' if pv else '<span></span>')+(f'<a href="{nx["slug"]}.html"><small>Next &rarr;</small><span>{E(nx["title"])}</span></a>' if nx else '<span></span>')
    rel=''.join(f'<a class="rv" href="{b["slug"]}.html"><div class="shot"><img src="{p}{b["image"]}" alt="{E(b["imageAlt"])}" width="800" height="500" loading="lazy"></div><div class="t"><h3>{E(b["title"])}</h3><small>{rt(b)}</small></div></a>' for b in related(a))
    pg+=f'''<main id="main"><div class="wrap art">
<nav class="crumbs" aria-label="Breadcrumb"><a href="{p}index.html">Home</a><span>/</span><a href="{p}resources.html">Resources</a><span>/</span><a href="{p}resources.html#{c['id']}">{E(c['label'])}</a></nav>
<header class="ahead stg"><a class="cat" href="{p}resources.html#{c['id']}">{E(c['label'])}</a><h1>{E(a['title'])}</h1><p class="intro2">{E(a['description'])}</p>
<div class="by"><span>By <b>{E(a['author'])}</b></span><span>Published: {fd(a['date'])}</span><span>Updated: {fd(a.get('updated'))}</span><span>{rt(a)}</span></div>{ban}</header>
<figure class="hero-img"><img src="{p}{a['image']}" alt="{E(a['imageAlt'])}" width="800" height="450"></figure>
<div class="alay"><aside class="toc" aria-label="Table of contents"><b>On this page</b><ol>{tochtml}</ol></aside><article class="prose">{body}</article></div>
<div class="afoot"><div class="abox"><span class="av" aria-hidden="true">RH</span><div><strong>{E(au['name'])}</strong><p>{E(au['role'])}. {E(au['bio'])}</p></div></div>
<ul class="tags" aria-label="Tags">{''.join(f'<li>{E(t)}</li>' for t in a['tags'])}</ul>
<div class="share"><span>Share:</span><a data-share="linkedin" target="_blank" rel="noopener" href="#">LinkedIn</a><a data-share="facebook" target="_blank" rel="noopener" href="#">Facebook</a><a data-share="x" target="_blank" rel="noopener" href="#">X</a></div>
<div class="pn">{pn}</div><div><a class="btn ghost" href="{p}resources.html">&larr; Back to All Resources</a></div></div>
</div>
<section class="more2"><div class="wrap"><h2>Continue Reading</h2><div class="rl">{rel}</div></div></section></main>
'''+foot(p)+'<script src="../js/content.js"></script><script src="../js/icons.js"></script><script src="../js/article.js"></script>\n</body></html>'
    open(f'resources/{a["slug"]}.html','w').write(pg)
# ---------- sitemap + robots
U=['','about','portfolio','resources','contact']+['resources/'+a['slug'] for a in V if a['status']=='published']
open('sitemap.xml','w').write('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{SU}/{u}</loc></url>\n' for u in U)+'</urlset>\n')
open('robots.txt','w').write(f'User-agent: *\nAllow: /\nSitemap: {SU}/sitemap.xml\n')
open('.htaccess','w').write('# Clean URLs (Apache): /resources -> resources.html\nRewriteEngine On\nRewriteCond %{REQUEST_FILENAME}.html -f\nRewriteRule ^(.*)$ $1.html [L]\n')
print(len(V),'visible;',len([a for a in V if a['status']=='published']),'in sitemap')
